Item.method_code:
/*
    パス非表示メソッドを呼び出す。
*/
Innovator inn = this.getInnovator();

const string targetPathName = "YryrReview";
Aras.Server.Security.Identity adminIdentity = Aras.Server.Security.Identity.GetByName("Administrators");

//thisからActivityのidを取得
string id = this.getProperty("id");

string body = "<targetPathName>"+targetPathName+"</targetPathName><acId>"+id+"</acId>";
using (CCO.Permissions.GrantIdentity(adminIdentity))
{
    var retItem = inn.applyMethod("h4_hidePath",body);
    if(retItem.isError())
    {
        //エラー
        return inn.newError(retItem.getErrorString());
    }
}
return this;
